<?php require dirname(__DIR__).'/layouts/admin_start.php';$h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<nav class="nc-module-nav"><a href="/notifications">Notificações</a><a class="active" href="/notifications/analyses">Análises</a></nav>
<section class="notification-metrics analysis-metrics"><?php foreach([['IN_ANALYSIS','Em análise'],['IN_FOLLOW_UP','Em acompanhamento'],['COMPLETED','Concluídas']]as$m):?><a href="?status=<?= $m[0] ?>"><strong><?= $counts[$m[0]] ?></strong><span><?= $m[1] ?></span></a><?php endforeach;?></section>
<form class="card notification-filters analysis-filters" method="get"><label>De<input type="date" name="from" value="<?= $h($_GET['from']??'') ?>"></label><label>Até<input type="date" name="to" value="<?= $h($_GET['to']??'') ?>"></label><?php if($canViewAll):?><label>Origem<select name="unit"><option value="">Todas</option><?php foreach($units as$u):?><option value="<?= $u['id'] ?>"><?= $h($u['name']) ?></option><?php endforeach;?></select></label><?php endif;?><label>Hemocomponente<select name="component"><option value="">Todos</option><?php foreach($components as$c):?><option value="<?= $c['id'] ?>"><?= $h($c['name']) ?></option><?php endforeach;?></select></label><label>Teste<select name="test"><option value="">Todos</option><?php foreach($tests as$t):?><option value="<?= $t['id'] ?>"><?= $h($t['name']) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">Todos</option><option value="IN_ANALYSIS">Em análise</option><option value="IN_FOLLOW_UP">Em acompanhamento</option><option value="COMPLETED">Concluída</option></select></label><label>Código<input name="code" value="<?= $h($_GET['code']??'') ?>" placeholder="ANL-..."></label><button class="button button-primary">Filtrar</button></form>
<div class="card analysis-table-wrap"><table class="analysis-table"><thead><tr><th>Análise</th><th>Origem</th><th>Período</th><th>Hemocomponente</th><th>Teste(s)</th><th>Ocorrências</th><th>Ações</th><th>Status</th><th>Atualização</th></tr></thead><tbody><?php foreach($analyses as$a):?><tr><td><a href="/notifications/analyses/view?id=<?= $a['id'] ?>"><strong><?= $h($a['analysis_code']) ?></strong></a></td><td><?= $h($a['unit_name']) ?></td><td><?= date('d/m/Y',strtotime($a['period_start'])) ?><br><?= date('d/m/Y',strtotime($a['period_end'])) ?></td><td><?= $h($a['component_name']?:'—') ?></td><td><?php foreach(explode('||',(string)$a['test_names']) as$testName):?><?php if($testName!==''):?><span class="analysis-list-test"><?= $h($testName) ?></span><?php endif;?><?php endforeach;?></td><td><?= $a['occurrence_count'] ?></td><td><?= $a['action_count'] ?></td><td><span class="notification-status status-<?= strtolower($a['status']) ?>"><?= $a['status']==='IN_ANALYSIS'?'Em análise':($a['status']==='IN_FOLLOW_UP'?'Em acompanhamento':'Concluída') ?></span></td><td><?= date('d/m/Y H:i',strtotime($a['updated_at'])) ?></td></tr><?php endforeach;?><?php if(!$analyses):?><tr><td colspan="9" class="empty-state">Nenhuma análise encontrada.</td></tr><?php endif;?></tbody></table></div>
<?php require dirname(__DIR__).'/layouts/admin_end.php'; ?>
